// Public landing page. Data (lots, amenities, plans, stats) comes from GET /api/public/overview.
import { get } from '../../api.js';
import { session, homeFor, isDriver } from '../../session.js';
import { money, pad, todayKey } from '../../format.js';
import { nowMs } from '../../clock.js';

// Two partner badge images shown only on this landing page, inlined as data URIs so this
// single file is a self-contained drop-in replacement (no extra image files to copy).
const BMS_HEADER_BADGE = 'data:image/png;base64,';
const BMS_FOOTER_BADGE = 'data:image/png;base64,';

const HERO_DURATIONS = [
  { m: 60, l: '1 hour' }, { m: 120, l: '2 hours' }, { m: 180, l: '3 hours' }, { m: 240, l: '4 hours' },
  { m: 360, l: '6 hours' }, { m: 480, l: '8 hours' }, { m: 720, l: '12 hours' },
];

// tiny decorative slot grid inside the phone mock-up (A-D x 6)
const MOCK = [
  ['booked', 'available', 'available', 'booked', 'available', 'buffer'],
  ['available', 'booked', 'available', 'available', 'booked', 'available'],
  ['available', 'available', 'you', 'available', 'blocked', 'available'],
  ['booked', 'available', 'available', 'buffer', 'available', 'booked'],
];

const SCENARIOS = {
  normal: {
    title: 'A normal booking',
    text: 'You park for the time you paid for. The slot then stays closed for 45 minutes so the next driver never arrives to find your car still there.',
    segs: [{ c: 'a', f: 8, t: 'Your booking' }, { c: 'buf', f: 3, t: '45 min turnaround' }, { c: 'b', f: 6, t: 'Next driver' }],
    ticks: ['Start', 'Your end time', '+45 min', 'Next booking can start'],
  },
  extend: {
    title: 'Need a bit longer?',
    text: 'Extend the same slot from your phone before your time is up - you pay only the extra time. If someone is booked right after you, the app tells you exactly how much you can add.',
    segs: [{ c: 'a', f: 8, t: 'Your booking' }, { c: 'ext', f: 3, t: '+30 min extension' }, { c: 'buf', f: 3, t: '45 min gap' }, { c: 'b', f: 6, t: 'Next driver' }],
    ticks: ['Start', 'Original end', 'New end', 'Next booking can start'],
  },
  overstay: {
    title: 'Stayed too long?',
    text: 'Leaving after your end time is charged as a fine at 1.5x the hourly rate for every started 15 minutes. Pay it in the app - it also protects the next driver\'s slot.',
    segs: [{ c: 'a', f: 8, t: 'Your booking' }, { c: 'fine', f: 3, t: 'Overstay fine' }, { c: 'buf', f: 3, t: '45 min gap' }, { c: 'b', f: 6, t: 'Next driver' }],
    ticks: ['Start', 'End time', 'You leave', 'Next booking can start'],
  },
};

const FEATURES = [
  { i: 'bi-map', t: 'See the slot before you go', d: 'A live floor plan shows every bay - free, booked, closed or in its turnaround gap. Pick your exact slot and get directions to it: level, row and bay.' },
  { i: 'bi-clock-history', t: 'Times that are always right', d: 'You choose a date and time in your own timezone; we store it in UTC and show it back in your local time. Bookings can never land on the wrong hour.' },
  { i: 'bi-plus-circle', t: 'Extend in two taps', d: 'Running late? Add 15 minutes or more to the same slot with a live price - as long as nobody is booked right after you.' },
  { i: 'bi-hourglass-split', t: 'A fair 45-minute gap', d: 'Every slot rests for 45 minutes between bookings, so handovers are smooth and nobody gets a "sorry, it is still occupied".' },
  { i: 'bi-ev-station', t: 'Amenities you can book', d: 'Add EV charging, a car wash or valet at checkout. Fuel, garage, gadget shops and cafes are shown on the lot page too.' },
  { i: 'bi-wallet2', t: 'Cashless & subscriptions', d: 'Pay by card or UPI. Regular parker? A monthly, 6-month or yearly plan gives you free parkings and washes.' },
];

const FAQ = [
  { q: 'How does the 45-minute buffer work?', a: 'After every booking the slot is kept empty for 45 minutes. Another driver can book that slot only if their booking starts after that gap - the slot map shows it as "turnaround gap" so you always know why a bay is unavailable.' },
  { q: 'What if I need more time?', a: 'Open your booking and tap Extend. Choose how much longer you need (in 15-minute steps), see the extra price, and pay. Extensions must be made before your time ends and are limited by the next booking on that slot.' },
  { q: 'What happens if I stay past my time?', a: 'You are charged an overstay fine of 1.5x the hourly rate for every started 15 minutes. You will get an email nudge, and the fine can be paid in the app. Unpaid fines block new bookings until they are settled.' },
  { q: 'Can I cancel a booking?', a: 'Yes, any time before it starts. Cancel at least 60 minutes ahead for a full refund; later than that, 50% is refunded.' },
  { q: 'Are the payments real?', a: 'No - this build uses a demo payment gateway. Use card 4111 1111 1111 1111 (any future expiry, any CVV) for a successful payment, or 4000 0000 0000 0002 to see a decline. UPI IDs starting with "fail" are declined.' },
  { q: 'I own a parking lot. Can I list it?', a: 'Yes. Create an owner account, define rows, columns and floors, set your price and amenities, and VparkEasy generates every slot automatically. You get a live operations console, revenue charts and fine management.' },
];

export default {
  data() {
    return {
      s: session,
      loading: true, error: '',
      stats: { lots: 0, slots: 0, cities: 0, bookings: 0 },
      lots: [], plans: [], amenities: [], buffer: 45,
      menu: false, scrolled: false, scenario: 'normal', openFaq: 0,
      search: { lotId: '', date: '', time: '', dur: 120 },
      durations: HERO_DURATIONS, mock: MOCK, features: FEATURES, faq: FAQ, scenarios: SCENARIOS,
    };
  },
  computed: {
    sc() { return SCENARIOS[this.scenario]; },
    today() { return todayKey(nowMs()); },
    loggedIn() { return !!(this.s.token && this.s.user); },
    bookable() { return this.amenities.filter(a => a.category === 'bookable'); },
    // The landing page is a simple showcase, not a live directory - always show a small,
    // fixed-size sample (max 3) so it doesn't grow every time an owner adds a new lot.
    sampleLots() { return this.lots.slice(0, 3); },
  },
  created() {
    this.initSearch();
    this.load();
  },
  mounted() {
    window.addEventListener('scroll', this.onScroll, { passive: true });
    this.onScroll();
    this.$nextTick(this.observe);
  },
  beforeDestroy() {
    window.removeEventListener('scroll', this.onScroll);
    if (this.io) this.io.disconnect();
  },
  methods: {
    money,
    initSearch() {
      // default: the next quarter hour at least 15 minutes from now, in the visitor's local time
      const t = new Date(nowMs() + 15 * 60000);
      t.setMinutes(Math.ceil(t.getMinutes() / 15) * 15, 0, 0);
      this.search.date = todayKey(t.getTime());
      this.search.time = `${pad(t.getHours())}:${pad(t.getMinutes())}`;
    },
    async load() {
      try {
        const d = await get('/api/public/overview');
        this.stats = d.stats; this.lots = d.lots; this.plans = d.plans; this.amenities = d.amenities;
        this.buffer = d.rules.buffer_minutes;
        if (this.lots.length) this.search.lotId = this.lots[0].id;
      } catch (e) {
        this.error = e.message;
      }
      this.loading = false;
      this.$nextTick(this.observe);
    },
    onScroll() { this.scrolled = window.scrollY > 8; },
    observe() {
      const els = this.$el.querySelectorAll('.reveal:not(.in)');
      if (!('IntersectionObserver' in window)) { els.forEach(e => e.classList.add('in')); return; }
      if (!this.io) {
        this.io = new IntersectionObserver(entries => entries.forEach(en => {
          if (en.isIntersecting) { en.target.classList.add('in'); this.io.unobserve(en.target); }
        }), { threshold: 0.08, rootMargin: '0px 0px -30px 0px' });
      }
      els.forEach(e => this.io.observe(e));
    },
    go(id) {
      this.menu = false;
      const el = document.getElementById(id);
      if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    },
    bookPath(lotId, q) {
      return { path: `/app/book/${lotId}`, query: q || {} };
    },
    startBooking(lotId, q) {
      const target = this.bookPath(lotId, q);
      if (this.loggedIn) {
        if (isDriver()) return this.$router.push(target);
        this.$toast.info('Sign in with a user account to book parking.');
        return this.$router.push(homeFor());
      }
      const next = this.$router.resolve(target).href;
      this.$router.push({ path: '/login', query: { next, as: 'user' } });
    },
    submitSearch() {
      if (!this.search.lotId) return;
      this.startBooking(this.search.lotId, { date: this.search.date, time: this.search.time, dur: this.search.dur });
    },
    per(p) {
      const d = p.duration_days;
      if (d >= 360) return 'year';
      if (d >= 60) return `${Math.round(d / 30)} months`;
      return 'month';
    },
    cover(i) { return 'v' + (i % 3); },
    tagOf(a) { return a.category === 'bookable' ? 'Book in app' : 'On-site'; },
    homePath() { return homeFor(); },
    mockIcon(s) { return { booked: 'bi-car-front-fill', buffer: 'bi-hourglass-split', blocked: 'bi-slash-circle', you: 'bi-geo-alt-fill' }[s] || ''; },
    mockClass(s) { return s === 'you' ? ['slot', 'available', 'highlight'] : ['slot', s]; },
  },
  template: `
  <div class="lp">
    <!-- ================= NAV ================= -->
    <header :class="['lp-nav', { scrolled }]">
      <div class="lp-container lp-nav-in">
        <div class="lp-brand-group" style="flex-wrap:wrap">
          <router-link to="/" class="logo" style="flex:none"><img src="/static/img/logo-mark.png" alt=""><span><b>Vpark</b><em>Easy</em></span></router-link>
          <span class="brand-sep"></span>
          <img src="${BMS_HEADER_BADGE}" alt="BMS - Park smart. Drive easy." title="Park smart. Drive easy." style="height:clamp(22px,7vw,34px);width:auto;border-radius:8px;object-fit:contain;box-shadow:0 1px 4px rgba(21,26,51,.18);flex:none">
        </div>
        <nav :class="['lp-links', { open: menu }]">
          <a class="nl" @click="go('how')">How it works</a>
          <a class="nl" @click="go('features')">Features</a>
          <a class="nl" @click="go('amenities')">Amenities</a>
          <a class="nl" @click="go('lots')">Parking lots</a>
          <a class="nl" @click="go('plans')">Plans</a>
          <a class="nl" @click="go('faq')">FAQ</a>
        </nav>
        <div class="lp-cta">
          <template v-if="loggedIn">
            <button class="btn btn-sm" @click="$router.push(homePath())"><i class="bi bi-speedometer2"></i> Open dashboard</button>
          </template>
          <template v-else>
            <router-link to="/login" class="btn btn-sm btn-ghost">Sign in</router-link>
            <router-link to="/register" class="btn btn-sm">Get started</router-link>
          </template>
          <button class="icon-btn lp-burger" @click="menu = !menu" aria-label="Menu"><i :class="['bi', menu ? 'bi-x-lg' : 'bi-list']"></i></button>
        </div>
      </div>
    </header>

    <!-- ================= HERO ================= -->
    <section class="hero">
      <div class="lp-container hero-grid">
        <div>
          <div class="hero-badges">
            <span class="hero-badge"><i class="bi bi-lightning-charge-fill"></i> Live slot maps</span>
            <span class="hero-badge"><i class="bi bi-hourglass-split"></i> {{ buffer }}-min fair turnaround</span>
          </div>
          <p style="display:flex;align-items:center;gap:8px;font-weight:800;font-size:.82rem;letter-spacing:.04em;text-transform:uppercase;color:var(--brand-600);margin:0 0 12px">VparkEasy — Where every ride has a spot. <span style="color:var(--line)">•</span> Park. Ride. Repeat.</p>
          <h1>Find it. Book it.<br><span class="grad">Park easy.</span></h1>
          <p class="lead">Reserve your exact parking slot in seconds, add EV charging or a car wash, extend from your phone and never argue about an occupied bay again.</p>

          <form class="searchcard" @submit.prevent="submitSearch" v-if="lots.length">
            <div class="field"><label for="hs-lot">Parking lot</label>
              <select id="hs-lot" class="select" v-model="search.lotId">
                <option v-for="l in lots" :key="l.id" :value="l.id">{{ l.name }} · {{ l.city }}</option>
              </select></div>
            <div class="field"><label for="hs-date">Date</label>
              <input id="hs-date" type="date" class="input" v-model="search.date" :min="today"></div>
            <div class="field"><label for="hs-time">Arrive</label>
              <input id="hs-time" type="time" class="input" v-model="search.time"></div>
            <div class="field"><label for="hs-dur">For</label>
              <select id="hs-dur" class="select" v-model.number="search.dur">
                <option v-for="d in durations" :key="d.m" :value="d.m">{{ d.l }}</option>
              </select></div>
            <button class="btn btn-lg" type="submit"><i class="bi bi-search"></i> Find slot</button>
          </form>
          <div v-else-if="loading" class="skeleton" style="height:84px;max-width:780px"></div>
          <div v-else-if="error" class="alert warn" style="max-width:780px"><i class="bi bi-wifi-off"></i><div>{{ error }}</div></div>

          <div class="hero-trust">
            <span><i class="bi bi-shield-check"></i> Secure payments</span>
            <span><i class="bi bi-geo-alt"></i> Directions to your bay</span>
            <span><i class="bi bi-envelope-check"></i> Instant confirmation e-mail</span>
          </div>
        </div>

        <div class="hero-visual" aria-hidden="true">
          <div class="float-chip c1"><span class="ic"><i class="bi bi-check2-circle"></i></span><div>Slot C3 confirmed<small>Level 1 · Row C · Bay 3</small></div></div>
          <div class="phone">
            <div class="phone-screen">
              <div class="phone-bar"><span>Central Mall Parking</span><span class="pill ok"><i class="bi bi-p-square-fill"></i> 14 free</span></div>
              <div class="phone-map">
                <div class="plan-frame">
                  <template v-for="(pair, pi) in [[0, 1], [2, 3]]">
                    <div v-if="pi > 0" class="lane" :key="'l' + pi"><span>drive lane</span></div>
                    <div class="bay-pair" :key="'p' + pi">
                      <div class="bay-line" v-for="r in pair" :key="r">
                        <span class="rowlabel">{{ 'ABCD'[r] }}</span>
                        <span v-for="(s, c) in mock[r]" :key="c" :class="mockClass(s)"><span class="sn">{{ 'ABCD'[r] }}{{ c + 1 }}</span><i v-if="mockIcon(s)" :class="['bi st', mockIcon(s)]"></i></span>
                      </div>
                    </div>
                  </template>
                </div>
              </div>
              <div class="phone-card">
                <span class="ic"><i class="bi bi-geo-alt-fill"></i></span>
                <div class="grow"><div class="strong">Your slot: C3</div><div class="tiny muted">Level 1 · 2nd row from entrance</div></div>
                <span class="strong ok-text">₹80</span>
              </div>
            </div>
          </div>
          <div class="float-chip c2"><span class="ic"><i class="bi bi-hourglass-split"></i></span><div>{{ buffer }} min gap<small>kept between bookings</small></div></div>
        </div>
      </div>
    </section>

    <!-- ================= STATS ================= -->
    <section class="stats">
      <div class="lp-container">
        <div class="stats-in reveal">
          <div class="stat"><b>{{ stats.lots }}</b><span>Parking lots</span></div>
          <div class="stat"><b>{{ stats.slots }}</b><span>Bookable slots</span></div>
          <div class="stat"><b>{{ stats.cities }}</b><span>Cities</span></div>
          <div class="stat"><b>{{ stats.bookings }}</b><span>Bookings made</span></div>
        </div>
      </div>
    </section>

    <!-- ================= HOW IT WORKS ================= -->
    <section id="how">
      <div class="lp-container">
        <div class="sec-head center-head reveal">
          <div class="eyebrow">How it works</div>
          <h2 class="sec-title">From "where do I park?" to parked in four steps</h2>
        </div>
        <div class="steps">
          <div class="step reveal"><span class="num">1</span><i class="bi bi-search ic"></i><h4>Pick a lot & time</h4><p>Choose where and when. Prices and free slots are shown before you commit.</p></div>
          <div class="step reveal"><span class="num">2</span><i class="bi bi-grid-3x3-gap ic"></i><h4>Choose your slot</h4><p>Tap a free bay on the live map. EV bays are marked; busy bays show when they free up.</p></div>
          <div class="step reveal"><span class="num">3</span><i class="bi bi-credit-card ic"></i><h4>Pay & get your ticket</h4><p>Card or UPI. Add a car wash or EV charging. Your booking code arrives by e-mail.</p></div>
          <div class="step reveal"><span class="num">4</span><i class="bi bi-p-square ic"></i><h4>Park, extend or leave</h4><p>Check in, follow the map to your bay, extend if you need to, then check out.</p></div>
        </div>
      </div>
    </section>

    <!-- ================= FEATURES ================= -->
    <section id="features" class="features">
      <div class="lp-container">
        <div class="sec-head reveal">
          <div class="eyebrow">Why drivers like it</div>
          <h2 class="sec-title">Built around the things that go wrong at parking lots</h2>
        </div>
        <div class="feat-grid">
          <div class="feat reveal" v-for="f in features" :key="f.t">
            <div class="ic"><i :class="['bi', f.i]"></i></div>
            <h4>{{ f.t }}</h4><p>{{ f.d }}</p>
          </div>
        </div>
      </div>
    </section>

    <!-- ================= FAIR PLAY ================= -->
    <section class="fair" id="fair">
      <div class="lp-container">
        <div class="sec-head reveal">
          <div class="eyebrow">Fair for everyone</div>
          <h2 class="sec-title">Extensions, fines and a {{ buffer }}-minute breather - explained</h2>
          <p class="sec-sub">Three simple rules keep every slot available when its next driver arrives.</p>
        </div>
        <div class="tl-demo reveal">
          <div class="seg" style="background:rgba(255,255,255,.1)">
            <button v-for="(v, k) in scenarios" :key="k" :class="{ active: scenario === k }" @click="scenario = k">{{ k === 'normal' ? 'Normal' : k === 'extend' ? 'Extend' : 'Overstay' }}</button>
          </div>
          <h3 style="color:#fff;margin:18px 0 4px">{{ sc.title }}</h3>
          <p style="color:#b5bcd8;max-width:720px">{{ sc.text }}</p>
          <div class="tl-track">
            <div v-for="(g, i) in sc.segs" :key="scenario + i" :class="['tl-seg', g.c]" :style="{ flex: g.f }">{{ g.t }}</div>
          </div>
          <div class="tl-ticks"><span v-for="t in sc.ticks" :key="t">{{ t }}</span></div>
        </div>
        <div class="fair-cards">
          <div class="fair-card reveal"><i class="bi bi-hourglass-split"></i><h4>{{ buffer }}-minute buffer</h4><p>No two bookings on a slot are closer than {{ buffer }} minutes. Time for a car to leave, the bay to be checked, and the next one to arrive.</p></div>
          <div class="fair-card reveal"><i class="bi bi-plus-circle-dotted"></i><h4>Pay-as-you-extend</h4><p>Need longer? Extend the same slot at the same rate in 15-minute steps - only if the slot is still free.</p></div>
          <div class="fair-card reveal"><i class="bi bi-exclamation-triangle"></i><h4>Overstay fine</h4><p>Leaving late costs 1.5x the hourly rate per started 15 minutes, payable in the app. Nobody is towed, nobody is surprised.</p></div>
        </div>
      </div>
    </section>

    <!-- ================= AMENITIES ================= -->
    <section id="amenities">
      <div class="lp-container">
        <div class="sec-head center-head reveal">
          <div class="eyebrow">Amenities</div>
          <h2 class="sec-title">More than a place to leave the car</h2>
          <p class="sec-sub">Charge, wash, refuel, repair or grab a coffee - see what each lot offers before you book. Items marked <b>Book in app</b> can be added at checkout.</p>
        </div>
        <div class="am-grid">
          <div class="am reveal" v-for="a in amenities" :key="a.code">
            <span class="amenity-icon"><i :class="['bi', a.icon]"></i></span>
            <div><h4>{{ a.name }}</h4><p>{{ a.description }}</p><span :class="['tag', a.category === 'bookable' ? '' : 'on']">{{ tagOf(a) }}</span></div>
          </div>
        </div>
        <div v-if="loading" class="spinner"></div>
      </div>
    </section>

    <!-- ================= LOTS ================= -->
    <section id="lots" class="features">
      <div class="lp-container">
        <div class="sec-head reveal">
          <div class="eyebrow">Parking lots</div>
          <h2 class="sec-title">A few lots you can book right now</h2>
          <p class="sec-sub" v-if="stats.lots > sampleLots.length">Just a taste - {{ stats.lots }} lots and {{ stats.slots }} slots are live once you sign in.</p>
        </div>
        <div class="lot-cards">
          <article class="lot-card reveal" v-for="(l, i) in sampleLots" :key="l.id">
            <div :class="['lot-cover', cover(i)]">
              <div><div class="tiny" style="opacity:.85">{{ l.city }}</div><div class="strong">{{ l.number_of_spots }} slots · {{ l.floors }} level{{ l.floors > 1 ? 's' : '' }}</div></div>
              <div class="price">{{ money(l.price_per_hour) }}<small>/hour</small></div>
            </div>
            <div class="lot-body">
              <h4>{{ l.name }}</h4>
              <div class="small muted"><i class="bi bi-geo-alt"></i> {{ l.address }}, {{ l.city }} {{ l.pin_code }}</div>
              <div class="flex items-center gap-1"><span class="pill ok"><span class="dot"></span>{{ l.free_now }} free now</span><span class="pill">{{ l.buffer_minutes }} min gap</span></div>
              <amenity-chips :amenities="l.amenities" :limit="5"></amenity-chips>
              <div class="grow"></div>
              <button class="btn btn-block" @click="startBooking(l.id)"><i class="bi bi-calendar2-check"></i> Book a slot</button>
            </div>
          </article>
        </div>
      </div>
    </section>

    <!-- ================= PLANS ================= -->
    <section id="plans" v-if="plans.length">
      <div class="lp-container">
        <div class="sec-head center-head reveal">
          <div class="eyebrow">Subscriptions</div>
          <h2 class="sec-title">Park often? Pay less.</h2>
          <p class="sec-sub">Each plan gives you free parkings (first 4 hours of each) and free car washes. New accounts also get 60 free minutes.</p>
        </div>
        <div class="plans">
          <div v-for="p in plans" :key="p.id" :class="['plan reveal', { pop: p.badge }]">
            <span class="badge" v-if="p.badge">{{ p.badge }}</span>
            <h3>{{ p.name }}</h3>
            <div class="muted small">{{ p.description }}</div>
            <div class="pr">{{ money(p.price) }}<small> / {{ per(p) }}</small></div>
            <ul>
              <li v-for="f in p.features" :key="f"><i class="bi bi-check-circle-fill"></i>{{ f }}</li>
            </ul>
            <router-link :to="{ path: '/register', query: { as: 'user' } }" :class="['btn btn-block', p.badge ? '' : 'btn-outline']">Get started</router-link>
          </div>
        </div>
      </div>
    </section>

    <!-- ================= OWNERS ================= -->
    <section style="padding-top:0">
      <div class="lp-container">
        <div class="owners reveal">
          <div class="owners-grid">
            <div>
              <div class="eyebrow" style="color:#b9fce2">For lot owners</div>
              <h2>Run your parking lot like a pro</h2>
              <p>Define your layout, set the price and amenities - VparkEasy creates every slot and handles bookings, payments and fines for you.</p>
              <ul>
                <li><i class="bi bi-grid-3x3-gap-fill"></i>Rows, columns and floors turned into slots automatically</li>
                <li><i class="bi bi-activity"></i>Live operations console: arrivals, parked cars, overstays</li>
                <li><i class="bi bi-graph-up-arrow"></i>Revenue, occupancy and peak-hour analytics</li>
              </ul>
              <router-link :to="{ path: '/register', query: { as: 'admin' } }" class="btn btn-lg" style="background:#fff;color:#065f47">List my lot <i class="bi bi-arrow-right"></i></router-link>
            </div>
            <div class="owner-mock" aria-hidden="true">
              <div class="flex between items-center"><b>Today</b><span class="pill ok">+18%</span></div>
              <div style="font-size:1.8rem;font-weight:800;letter-spacing:-.03em">₹12,480</div>
              <div class="tiny muted">Revenue · 46 bookings</div>
              <div class="bars"><i style="height:38%"></i><i style="height:52%"></i><i style="height:44%"></i><i style="height:70%"></i><i style="height:58%"></i><i style="height:86%"></i><i style="height:100%"></i></div>
            </div>
          </div>
        </div>
      </div>
    </section>

    <!-- ================= FAQ ================= -->
    <section id="faq" class="features">
      <div class="lp-container">
        <div class="sec-head center-head reveal">
          <div class="eyebrow">FAQ</div>
          <h2 class="sec-title">Questions, answered</h2>
        </div>
        <div class="faq">
          <div v-for="(f, i) in faq" :key="i" :class="['faq-item reveal', { open: openFaq === i }]">
            <button class="faq-q" @click="openFaq = openFaq === i ? -1 : i" :aria-expanded="openFaq === i">{{ f.q }}<i class="bi bi-chevron-down"></i></button>
            <div class="faq-a" v-if="openFaq === i">{{ f.a }}</div>
          </div>
        </div>
      </div>
    </section>

    <section class="lp-cta-band">
      <div class="lp-container reveal">
        <h2>Ready to park easy?</h2>
        <p class="sec-sub" style="margin:0 auto 22px">Create a free account and get 60 minutes of parking on us.</p>
        <router-link to="/register" class="btn btn-lg">Create free account</router-link>
      </div>
    </section>

    <!-- ================= FOOTER ================= -->
    <footer class="lp-footer">
      <div class="lp-container">
        <div class="lp-footer-grid">
          <div><router-link to="/" class="logo" style="flex:none"><img src="/static/img/logo-mark.png" alt=""><span><b>Vpark</b><em>Easy</em></span></router-link><img src="${BMS_FOOTER_BADGE}" alt="BMS - Build. Manage. Solve." title="Build. Manage. Solve." style="display:block;height:40px;width:auto;border-radius:8px;object-fit:contain;box-shadow:0 1px 4px rgba(21,26,51,.18);background:#fff;padding:6px 10px;box-sizing:content-box;margin-top:10px"><p style="margin-top:14px;max-width:290px">Book the exact slot, pay in-app and leave without hassle.</p></div>
          <div><h5>Product</h5><a @click="go('how')">How it works</a><a @click="go('features')">Features</a><a @click="go('amenities')">Amenities</a><a @click="go('plans')">Plans</a></div>
          <div><h5>Account</h5><router-link to="/login">User sign in</router-link><router-link :to="{ path: '/login', query: { as: 'admin' } }">Owner sign in</router-link><router-link to="/register">Create account</router-link><router-link to="/partner/login">Partner sign in (captain/driver)</router-link><router-link to="/partner/register">Become a driver partner</router-link></div>
          <div><h5>Parking lots</h5><a v-for="l in sampleLots" :key="l.id" @click="startBooking(l.id)">{{ l.name }}</a></div>
        </div>
        <div class="lp-copy"><span>© 2024 VparkEasy - a BMS MotoVerse <i class="bi bi-car-front-fill" style="color:var(--brand-400);margin-left:2px"></i></span><span>Demo payment gateway - no real money is charged.</span></div>
      </div>
    </footer>
  </div>`,
};
